  ...vpc,
  securityGroups: vpc.securityGroups.map((g) => g.id === id
    ? { id, rules: [{ direction: "inbound" as const, protocol: "tcp" as const, fromPort: port, toPort: port, cidr: "0.0.0.0/0" }, { direction: "outbound" as const, protocol: "-1" as const, cidr: "0.0.0.0/0" }] }
